def max_score_difference(N, cards):
    def dp(i, j, turn):
        if i > j:
            return 0
        if turn == 'A':
            return max(cards[i] + dp(i + 1, j, 'B'), cards[j] + dp(i, j - 1, 'B'))
        else:
            return min(-cards[i] + dp(i + 1, j, 'A'), -cards[j] + dp(i, j - 1, 'A'))

    return dp(0, N - 1, 'A')

